// 在 Code 节点中运行一次性所有 items
let results = [];
for (const item of $input.all()) {
  for (const key of Object.keys(item.binary)) {
    results.push({
      json: item.json,
      binary: { data: item.binary[key] },
    });
  }
}
return results;

